// === Tab: mySketch ===
const NUM = 4, FRMS = 240;
let beziers, S, seed, BG;

function setup() {
	// createCanvas(windowWidth, windowHeight);
	createCanvas(S=max(windowWidth, windowHeight), S);
	S = max(width, height);
	frameRate(30);
	noFill();

	// seed
	seed = ~random(7654321);
	randomSeed(seed);
	noiseSeed(seed);

	BG = color(random(16, 48), random(16, 48), random(16, 48));

	// beziers def
	beziers = [];
	for (let i = 0; i < NUM; i++) {
		let lx, ly
		const pts = [], calcPts = (i > 0 && random()<0.65) ? 3 : 4, bezIdx = beziers.length-1;
		if (calcPts === 3) pts.push(beziers[bezIdx][6], beziers[bezIdx][7])
		for (let j = 0; j < calcPts; j++) {
			const x = random(width);
			const y = random(height);
			pts.push(x, y)
		}
		beziers.push(pts);
	}

	background("navy");
	background(BG);
	stroke("white");
	strokeWeight(2);
}

function draw() {
	for (let i = 0; i < beziers.length; i++) {
		const b = beziers[i];
		// bezier(...b);

		const idx = ~~(frameCount / FRMS) % beziers.length;
		const frg = (frameCount % FRMS) / FRMS;
		if (i === idx) drawBezPt(b, frg);
	}
}

function drawBezPt(bez, f) {
	// https://p5js.org/reference/p5/bezierPoint/
	push();
	strokeWeight(1);

	var x = bezierPoint(bez[0], bez[2], bez[4], bez[6], f);
	var y = bezierPoint(bez[1], bez[3], bez[5], bez[7], f);
	// circle(x, y, 7);

	const t = millis()/10000;
	const rr = noise (4*x/width, y/height, 100+t) * 300;
	const gg = noise (x/width, 3*y/height, 200+t) * 200;
	const bb = noise (2*x/width, 1.5*y/height, 300+t) * 255;
	const dd = noise (x/width, y/height, 400+t/100) * S * 0.25;

	fill(rr, gg, bb);
	noStroke();
	circle(x, y, dd);

	pop();
}

function mousePressed() {
	if (mouseButton.left && (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) > width*0.1) setup();
}
